function g({registerIndicator:y,sourceValues:b,nulls:N}){y({id:"oa-hwma",name:"Holt-Winters Moving Average (HWMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"hwma",type:"line",title:"HWMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,p){const i=Math.max(1,Math.floor(Number(p.period)||10)),A=b(c,p.source??"close"),m=2/(i+1),f=1/i,d=1/i,r=new Array(c.length).fill(NaN);let e=NaN,t=0,n=0;for(let o=0;o<c.length;o++){const l=A[o];if(!Number.isFinite(l)){if(!Number.isFinite(e))continue;const F=e,v=t,u=n;e=F+v+.5*u,t=v+u,n=.9*u,r[o]=e;continue}if(!Number.isFinite(e)){e=l,r[o]=e;continue}const h=e,a=t,s=n;e=m*l+(1-m)*(h+a+.5*s),t=f*(e-h)+(1-f)*(a+s),n=d*(t-a)+(1-d)*s,r[o]=e+t+.5*n}return{hwma:N(r)}}})}export{g as default};
